const VERSION='casa-obra-v5-1-final';
const CORE=['./','./index.html','./manifest.webmanifest','./offline.html','./supabase-config.js','./v5-0.js','./v5-1.js','./v5-2.js','./v5-3.js','./v5-4.js','./v5-extra.js','./v5.css','./icons/icon-192.png','./icons/icon-512.png','./icons/icon-maskable-512.png','./icons/apple-touch-icon.png','./icons/badge-96.png'];
self.addEventListener('install',e=>e.waitUntil(caches.open(VERSION).then(c=>c.addAll(CORE)).then(()=>self.skipWaiting())));
self.addEventListener('activate',e=>e.waitUntil(Promise.all([self.clients.claim(),caches.keys().then(keys=>Promise.all(keys.filter(k=>k!==VERSION).map(k=>caches.delete(k))))])));
self.addEventListener('fetch',e=>{if(e.request.method!=='GET')return;const u=new URL(e.request.url);if(e.request.mode==='navigate'){e.respondWith(fetch(e.request).then(r=>{const c=r.clone();caches.open(VERSION).then(x=>x.put(e.request,c));return r}).catch(async()=>await caches.match(e.request)||await caches.match('./index.html')||await caches.match('./offline.html')));return}e.respondWith(caches.match(e.request).then(cached=>{const net=fetch(e.request).then(r=>{if(r&&(r.ok||r.type==='opaque')){const copy=r.clone();caches.open(VERSION).then(c=>c.put(e.request,copy))}return r}).catch(()=>cached);return cached||net}))});
self.addEventListener('push',e=>{let d={title:'Casa & Obra',body:'Você recebeu uma nova atualização.',url:'./?tab=home',tag:'casa-obra'};try{if(e.data)d={...d,...e.data.json()}}catch(_){if(e.data)d.body=e.data.text()}e.waitUntil(self.registration.showNotification(d.title,{body:d.body,icon:d.icon||'./icons/icon-192.png',badge:d.badge||'./icons/badge-96.png',tag:d.tag||'casa-obra',data:{url:d.url||'./?tab=home',...(d.data||{})},renotify:Boolean(d.renotify)}))});
self.addEventListener('notificationclick',e=>{e.notification.close();const target=e.notification?.data?.url||'./?tab=home';e.waitUntil((async()=>{const list=await self.clients.matchAll({type:'window',includeUncontrolled:true});for(const c of list){if('focus'in c){await c.focus();if('navigate'in c)await c.navigate(target);return}}if(self.clients.openWindow)return self.clients.openWindow(target)})())});
